/** Outline icon in the trust-strip style: 1px round strokes on a 20×20 grid. */
function Outline({ className, children }: P & { children: ReactNode }) {
  return (
    <svg viewBox="0 0 20 20" className={className} fill="currentColor" aria-hidden focusable="false">
      <g fill="none" stroke="currentColor" strokeWidth={1} strokeLinecap="round" strokeLinejoin="round">
        {children}
      </g>
    </svg>
  );
}

