export const PDP_ICONS: Record<IconKey, (p: P) => JSX.Element> = {
  delivery: DoorstepDeliveryIcon,
  support: AfterSaleSupportIcon,
  quality: InternationalStandardIcon,
  assembly: AssemblyAssistanceIcon,
  warranty: WarrantyIcon,
  returns: ReturnsIcon,
  payment: PaymentIcon,
  cash: CashIcon,
  measure: MeasureIcon,
  leaf: LeafIcon,
  phone: PhoneIcon,
  chat: ChatIcon,
  star: StarIcon,
  store: StoreIcon,
  clock: ClockIcon,
  gift: GiftIcon,
};

/** The drawing for a stored icon key; unknown keys fall back to the delivery van. */
export function pdpIcon(key: string): (p: P) => JSX.Element {
  return PDP_ICONS[key as IconKey] ?? PDP_ICONS[DEFAULT_ICON];
}
